 "content": "def transform(grid):
    """Recolor any complete monochrome separator row or column to 2."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    separator_rows = [r for r, row in enumerate(out) if len(set(row)) == 1]
    separator_cols = [c for c in range(w) if len({out[r][c] for r in range(h)}) == 1]
    for r in separator_rows:
        for c in range(w):
            out[r][c] = 2
    for c in separator_cols:
        for r in range(h):
            out[r][c] = 2
